using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests
{
    [Fact]
    public void CanCreateDatabase_WithInMemoryProvider()
    {
        using var context = TestDbContextFactory.Create();

        Assert.NotNull(context.Students);
        Assert.NotNull(context.Courses);
        Assert.NotNull(context.Departments);
        Assert.NotNull(context.Instructors);
        Assert.NotNull(context.Enrollments);
        Assert.NotNull(context.CourseAssignments);
        Assert.NotNull(context.OfficeAssignments);
        Assert.NotNull(context.Notifications);
    }

    [Fact]
    public void CanAddAndRetrieveStudent()
    {
        using var context = TestDbContextFactory.Create();
        var student = new Student
        {
            LastName = "TestLast",
            FirstMidName = "TestFirst",
            EnrollmentDate = DateTime.Parse("2023-01-01")
        };

        context.Students.Add(student);
        context.SaveChanges();

        var retrieved = context.Students.First(s => s.LastName == "TestLast");
        Assert.Equal("TestFirst", retrieved.FirstMidName);
    }

    [Fact]
    public void CanAddAndRetrieveCourse()
    {
        using var context = TestDbContextFactory.Create();
        var dept = new Department
        {
            Name = "Test Dept",
            Budget = 100000,
            StartDate = DateTime.Now
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 5000,
            Title = "Test Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var retrieved = context.Courses.Find(5000);
        Assert.NotNull(retrieved);
        Assert.Equal("Test Course", retrieved.Title);
    }

    [Fact]
    public void CourseAssignment_HasCompositeKey()
    {
        using var context = TestDbContextFactory.Create();
        var instructor = new Instructor
        {
            LastName = "Smith",
            FirstMidName = "John",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Instructors.Add(instructor);

        var dept = new Department { Name = "Dept", Budget = 50000, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 6000,
            Title = "Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID,
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var assignment = new CourseAssignment
        {
            InstructorID = instructor.ID,
            CourseID = course.CourseID
        };
        context.CourseAssignments.Add(assignment);
        context.SaveChanges();

        var retrieved = context.CourseAssignments.Find(course.CourseID, instructor.ID);
        Assert.NotNull(retrieved);
    }

    [Fact]
    public void Instructor_CanHaveOfficeAssignment()
    {
        using var context = TestDbContextFactory.Create();
        var instructor = new Instructor
        {
            LastName = "Office",
            FirstMidName = "Test",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>(),
            OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var retrieved = context.Instructors
            .Include(i => i.OfficeAssignment)
            .First(i => i.LastName == "Office");
        Assert.NotNull(retrieved.OfficeAssignment);
        Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
    }

    [Fact]
    public void Student_CanHaveEnrollments()
    {
        using var context = TestDbContextFactory.Create();
        var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 7000,
            Title = "C",
            Credits = 3,
            DepartmentID = dept.DepartmentID,
            Enrollments = new List<Enrollment>()
        };
        context.Courses.Add(course);

        var student = new Student
        {
            LastName = "EnrollTest",
            FirstMidName = "S",
            EnrollmentDate = DateTime.Now,
            Enrollments = new List<Enrollment>()
        };
        context.Students.Add(student);
        context.SaveChanges();

        context.Enrollments.Add(new Enrollment
        {
            CourseID = course.CourseID,
            StudentID = student.ID,
            Grade = Grade.B
        });
        context.SaveChanges();

        var retrieved = context.Students
            .Include(s => s.Enrollments)
            .First(s => s.LastName == "EnrollTest");
        Assert.Single(retrieved.Enrollments);
        Assert.Equal(Grade.B, retrieved.Enrollments.First().Grade);
    }

    [Fact]
    public void Person_FullName_CombinesLastAndFirst()
    {
        var student = new Student
        {
            LastName = "Doe",
            FirstMidName = "Jane",
            EnrollmentDate = DateTime.Now
        };

        Assert.Equal("Doe, Jane", student.FullName);
    }

    [Fact]
    public void Department_CanHaveNullInstructorID()
    {
        using var context = TestDbContextFactory.Create();
        var dept = new Department
        {
            Name = "NoAdmin",
            Budget = 50000,
            StartDate = DateTime.Now,
            InstructorID = null
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        var retrieved = context.Departments.First(d => d.Name == "NoAdmin");
        Assert.Null(retrieved.InstructorID);
    }
}
