namespace ContosoUniversity.Tests.Controllers;

/// <summary>
/// Additional CoursesController tests for file upload edge cases.
/// </summary>
public class CoursesControllerFileTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;
    private readonly string _tempDir;

    public CoursesControllerFileTests()
    {
        _context = TestDbContextFactory.CreateWithSeedData();
        _tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
        Directory.CreateDirectory(_tempDir);
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
        _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        if (Directory.Exists(_tempDir))
            Directory.Delete(_tempDir, true);
    }

    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_Post_AllowedExtensions_AcceptsFile(string extension)
    {
        var course = new Course { CourseID = 5000 + extension.GetHashCode() % 1000 + 1000, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = CreateMockFormFile($"test{extension}", 1024);

        var result = _controller.Create(course, mockFile.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_WithValidImage_UpdatesImagePath()
    {
        // Use a fresh db to avoid tracking
        var dbName = Guid.NewGuid().ToString();
        using var seedCtx = TestDbContextFactory.Create(dbName);
        seedCtx.Departments.Add(new Department { DepartmentID = 1, Name = "D", Budget = 1000, StartDate = DateTime.Now });
        seedCtx.Courses.Add(new Course { CourseID = 2000, Title = "Edit Test", Credits = 3, DepartmentID = 1 });
        seedCtx.SaveChanges();

        using var testCtx = TestDbContextFactory.Create(dbName);
        using var controller = new CoursesController(testCtx, _mockEnv.Object, _mockLogger.Object);

        var course = new Course { CourseID = 2000, Title = "Edit Test", Credits = 3, DepartmentID = 1 };
        var mockFile = CreateMockFormFile("new.jpg", 2048);

        var result = controller.Edit(course, mockFile.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_FileTooLarge_ReturnsError()
    {
        var course = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 };
        var mockFile = CreateMockFormFile("big.png", 6 * 1024 * 1024);

        var result = _controller.Edit(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void DeleteConfirmed_CourseWithImage_DeletesFile()
    {
        // Create a file to be deleted
        var uploadsPath = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
        Directory.CreateDirectory(uploadsPath);
        var filePath = Path.Combine(uploadsPath, "test_delete.jpg");
        File.WriteAllText(filePath, "dummy");

        // Create a course with that image path
        var dbName = Guid.NewGuid().ToString();
        using var seedCtx = TestDbContextFactory.Create(dbName);
        seedCtx.Departments.Add(new Department { DepartmentID = 1, Name = "D", Budget = 1000, StartDate = DateTime.Now });
        seedCtx.Courses.Add(new Course
        {
            CourseID = 3000,
            Title = "Deletable",
            Credits = 3,
            DepartmentID = 1,
            TeachingMaterialImagePath = "/Uploads/TeachingMaterials/test_delete.jpg"
        });
        seedCtx.SaveChanges();

        using var testCtx = TestDbContextFactory.Create(dbName);
        using var controller = new CoursesController(testCtx, _mockEnv.Object, _mockLogger.Object);

        var result = controller.DeleteConfirmed(3000) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.False(File.Exists(filePath));
    }

    [Fact]
    public void DeleteConfirmed_CourseWithoutImage_Succeeds()
    {
        var dbName = Guid.NewGuid().ToString();
        using var seedCtx = TestDbContextFactory.Create(dbName);
        seedCtx.Departments.Add(new Department { DepartmentID = 1, Name = "D", Budget = 1000, StartDate = DateTime.Now });
        seedCtx.Courses.Add(new Course { CourseID = 3001, Title = "NoImage", Credits = 3, DepartmentID = 1 });
        seedCtx.SaveChanges();

        using var testCtx = TestDbContextFactory.Create(dbName);
        using var controller = new CoursesController(testCtx, _mockEnv.Object, _mockLogger.Object);

        var result = controller.DeleteConfirmed(3001) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    private static Mock<IFormFile> CreateMockFormFile(string fileName, long length)
    {
        var mock = new Mock<IFormFile>();
        mock.Setup(f => f.FileName).Returns(fileName);
        mock.Setup(f => f.Length).Returns(length);
        mock.Setup(f => f.CopyTo(It.IsAny<Stream>()));
        return mock;
    }
}
