using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.AspNetCore.Routing;

namespace ContosoUniversity.Tests.Controllers;

/// <summary>
/// Additional tests to boost coverage of InstructorsController async Edit
/// and UpdateInstructorCourses logic.
/// </summary>
public class InstructorsControllerEditTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerEditTests()
    {
        _context = TestDbContextFactory.CreateWithSeedData();
        _controller = new InstructorsController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public async Task Edit_Post_NullId_ReturnsBadRequest()
    {
        var result = await _controller.Edit(null, null!) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void DeleteConfirmed_InstructorWithoutDepartment_Succeeds()
    {
        // Instructor 2 is not administrator of any department
        var result = _controller.DeleteConfirmed(2) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Null(_context.Instructors.Find(2));
    }

    [Fact]
    public void Create_Post_NullSelectedCourses_NoAssignments()
    {
        var instructor = new Instructor
        {
            LastName = "NoCourses",
            FirstMidName = "Test",
            HireDate = DateTime.Parse("2020-01-15"),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!) as RedirectToActionResult;

        Assert.NotNull(result);
        var saved = _context.Instructors.First(i => i.LastName == "NoCourses");
        Assert.Empty(_context.CourseAssignments.Where(ca => ca.InstructorID == saved.ID));
    }
}

